const assert=require('assert');
(async()=>{
 const root='http://127.0.0.1:3000';
 const get=()=>fetch(root+'/api/workbooks/ops-plan').then(r=>r.json());
 let a=await get(), b=structuredClone(a);
 a.workbook.sheets[0].cells.F2='alpha';
 let r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:a.revision,workbook:a.workbook,userId:'riley',sessionId:'test-a'})}); assert.equal(r.status,200); let saved=await r.json(); assert.equal(saved.revision,2);
 b.workbook.sheets[0].cells.G2='beta';
 r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:b.revision,workbook:b.workbook,userId:'morgan',sessionId:'test-b'})}); assert.equal(r.status,200); saved=await r.json(); assert.equal(saved.revision,3); assert.equal(saved.workbook.sheets[0].cells.F2,'alpha');assert.equal(saved.workbook.sheets[0].cells.G2,'beta');
 const c=await get(),d=structuredClone(c);c.workbook.sheets[0].cells.H2='first';d.workbook.sheets[0].cells.H2='second';
 r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:c.revision,workbook:c.workbook,userId:'priya'})});assert.equal(r.status,200);
 r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:d.revision,workbook:d.workbook,userId:'morgan'})});assert.equal(r.status,409);
 let before=(await get()).revision;
 r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:before,workbook:{id:'ops-plan'},userId:'riley'})}); assert.equal(r.status,400);assert.equal((await get()).revision,before);
 r=await fetch(root+'/api/workbooks/ops-plan/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:before,workbook:{...(await get()).workbook,title:'Renamed'},userId:'riley'})});assert.equal(r.status,400);assert.equal((await get()).revision,before);
 console.log('API persistence, merge, conflict, and validation tests passed at revision',before);
})().catch(e=>{console.error(e);process.exit(1)})
